ALTER TABLE tenants ADD COLUMN loyalty_terms_accepted_at INTEGER;
ALTER TABLE tenants ADD COLUMN support_minutes INTEGER NOT NULL DEFAULT 0 CHECK(support_minutes>=0);
CREATE TABLE signup_challenges(hash TEXT PRIMARY KEY,email TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE signup_deliveries(id TEXT PRIMARY KEY,challenge_hash TEXT NOT NULL REFERENCES signup_challenges(hash),payload_cipher TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','leased','provider_accepted','failed_retryable','failed_final')),due_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,lease_until INTEGER,provider_id TEXT,reason TEXT);
CREATE TABLE provision_claims(challenge_hash TEXT PRIMARY KEY REFERENCES signup_challenges(hash),tenant_id TEXT NOT NULL UNIQUE REFERENCES tenants(id));
CREATE TRIGGER provision_guard BEFORE INSERT ON provision_claims BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM signup_challenges WHERE hash=NEW.challenge_hash AND used_at IS NULL AND expires_at>unixepoch()*1000 AND NOT EXISTS(SELECT 1 FROM merchant_users WHERE email=signup_challenges.email)) THEN RAISE(ABORT,'invalid_signup') END; UPDATE signup_challenges SET used_at=unixepoch()*1000 WHERE hash=NEW.challenge_hash; END;
CREATE TABLE merchant_assets(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),object_key TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,provenance TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,id));
CREATE TABLE prospect_previews(hash TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),snapshot TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER signup_no_reuse BEFORE UPDATE OF used_at ON signup_challenges WHEN OLD.used_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'signup_used'); END;
CREATE TRIGGER mode_change_guard BEFORE UPDATE OF business_mode ON tenants WHEN NEW.business_mode!=OLD.business_mode BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM bookings WHERE tenant_id=NEW.id) OR EXISTS(SELECT 1 FROM inquiries WHERE tenant_id=NEW.id) THEN RAISE(ABORT,'mode_has_activity') END; END;
CREATE TRIGGER asset_quota_guard BEFORE INSERT ON merchant_assets WHEN NOT EXISTS(SELECT 1 FROM merchant_assets WHERE id=NEW.id) BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM merchant_assets WHERE tenant_id=NEW.tenant_id)>=10 OR (SELECT COALESCE(SUM(size),0) FROM merchant_assets WHERE tenant_id=NEW.tenant_id)+NEW.size>2621440 THEN RAISE(ABORT,'asset_quota') END; END;
CREATE TABLE setup_operations(tenant_id TEXT NOT NULL REFERENCES tenants(id),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,subject TEXT NOT NULL,PRIMARY KEY(tenant_id,idempotency_key));
